SELECT id, reference_signal_id, evaluation_path, evaluated_at, replay_mode, one_hour_signal_id, one_hour_raw_decision, one_hour_effective_decision, one_hour_age_seconds, five_minute_signal_id, five_minute_raw_decision, five_minute_effective_decision, assessment_band, max_initial_percent, final_result, LEFT(final_reason,400) AS final_reason FROM buy_htf_assessment_audit WHERE reference_signal_id IN (115050,121201,133251,115049,121198) ORDER BY reference_signal_id, evaluated_at LIMIT 50;